#!/usr/bin/env python3
"""Generates Tests/Compiler/Srm24ExpStmt.lean: expected statements (fully qualified) of the SRM24 theorems, from the Lean text of
scripts/srm24/EXPECTED.txt (fixed before any proof file) with M/Q substitution, plus wrong-expected mutations.  usage: python3 -I scripts/srm24/gen_exp.py"""
HEAD = '''import Tests.Compiler.Srm24WidthTest
set_option autoImplicit false
-- GENERATED by scripts/srm24/gen_exp.py from scripts/srm24/EXPECTED.txt; do not edit.
namespace Tests.Compiler.Srm24ExpStmt
open Sparkle.IR.AST Sparkle.IR.OptCheck Sparkle.IR.HierCheck
'''
CTX = '''∀ {{mctx : Lean.Meta.Context}} {{mref : ST.Ref IO.RealWorld Lean.Meta.State}} {{cctx : Lean.Core.Context}} {{cref : ST.Ref IO.RealWorld Lean.Core.State}}
    {{w w1 : Void IO.RealWorld}} {{b raw : Module}} {{D : Design}}
    (hcore : Tools.ShippingEntrySoundness.RunsTo (Sparkle.Compiler.Elab.synthesizeCombinationalCore `Tests.Compiler.SharedLeafMemKidTest.{P} [] false) mctx mref cctx cref w (raw, D) w1)
    (hpost : b = Sparkle.IR.ZeroWidth.dropZeroWidthModule raw ∨ b = Sparkle.IR.RefineCheck.mergeChecked (Sparkle.IR.ZeroWidth.dropZeroWidthModule raw))
    (entry : Tools.ShippingMachineEntry.MachineDefines mctx mref cctx cref `Tests.Compiler.SharedLeafMemKidTest.{P} Tests.Compiler.SharedLeafMemKidTest.{P}.machineData.shape)
    (hBnd : Tests.Compiler.Srm9ComposedTest.{BND} mctx mref cctx cref w raw D)'''
GAP = 'Tools.ShippingSrm22Width.ShippedRegWidthLe b'
REG = '''(r c : String) (rs : String × Sparkle.IR.Type.ResetKind) (inp : Expr) (init : Int)'''
out = [HEAD]
out.append(f'''def Exp_generic : Prop := ∀ {{b : Module}} (hgate : Sparkle.IR.RefineCheck.hierGate b = true)
    (hwn : ∀ p ∈ b.wires, Sparkle.Backend.Verilog.sanitizeName p.name = p.name), {GAP}\n''')
out.append(f'''def Exp_regWidth : Prop := ∀ {{b : Module}} (hgate : Sparkle.IR.RefineCheck.hierGate b = true) {REG},
    Stmt.register r c rs inp init ∈ (checkedOptimize b).body → Sparkle.IR.RegDedup.declWidth b r = Sparkle.IR.RegDedup.declWidth (checkedOptimize b) r\n''')
COR = '''
    (st0 : String → Nat),
    Tools.ShippingSrm13Supply.RegsAtInit (checkedOptimize b) st0 →
      (∀ r ∈ seqRegs (openFlat b (openIns b) (openOuts b)), st0 r.1 < 2 ^ Sparkle.IR.RegDedup.declWidth b r.1) →
      Tools.ShippingSrm13Supply.RegsFit (checkedOptimize b)'''
for X, BND in (('M', 'TmBnd'), ('Q', 'TqBnd')):
    ctx = CTX.format(P='topshare' + X, BND=BND)
    out.append(f'def Exp_{X}_shippedRegWidthLe : Prop :=\n  {ctx},\n   {GAP}\n')
    out.append(f'def Exp_{X}_regsFit_noW : Prop :=\n  {ctx}{COR}\n')
ctxM = CTX.format(P='topshareM', BND='TmBnd')
# mutations (wrong expected forms, must be REJECTED)
out.append(f'def Exp_mut_hWKept : Prop :=\n  {ctxM}\n    (st0 : String → Nat) (hW : {GAP}),\n    Tools.ShippingSrm13Supply.RegsAtInit (checkedOptimize b) st0 →\n      (∀ r ∈ seqRegs (openFlat b (openIns b) (openOuts b)), st0 r.1 < 2 ^ Sparkle.IR.RegDedup.declWidth b r.1) →\n      Tools.ShippingSrm13Supply.RegsFit (checkedOptimize b)\n')
out.append(f'def Exp_mut_wrongGap : Prop :=\n  {ctxM},\n   Tools.ShippingSrm22Width.SourceRegsKept b\n')
ctxNoPost = ctxM.replace('    (hpost : b = Sparkle.IR.ZeroWidth.dropZeroWidthModule raw ∨ b = Sparkle.IR.RefineCheck.mergeChecked (Sparkle.IR.ZeroWidth.dropZeroWidthModule raw))\n', '')
out.append(f'def Exp_mut_noHpost : Prop :=\n  {ctxNoPost},\n   {GAP}\n')
out.append(f'def Exp_mut_noHwn : Prop := ∀ {{b : Module}} (hgate : Sparkle.IR.RefineCheck.hierGate b = true), {GAP}\n')
out.append('end Tests.Compiler.Srm24ExpStmt\n')
open('Tests/Compiler/Srm24ExpStmt.lean', 'w').write('\n'.join(out))
